-- OpsCore v0.11.50: general-purpose daily closure compilation and governed worker integration.
CREATE TABLE IF NOT EXISTS closure_sheets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, sheet_date TEXT NOT NULL, technician_id TEXT REFERENCES users(id) ON DELETE SET NULL, status TEXT NOT NULL CHECK(status IN ('ready','blocked')), item_count BIGINT NOT NULL DEFAULT 0 CHECK(item_count>=0), blocked_count BIGINT NOT NULL DEFAULT 0 CHECK(blocked_count>=0), sheet_sha256 TEXT NOT NULL, rows_json TEXT NOT NULL, compiled_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,sheet_date,technician_id));
CREATE INDEX IF NOT EXISTS idx_closure_sheets_org_date ON closure_sheets(organization_id,sheet_date,status);
